PRAGMA foreign_keys=ON;
CREATE TABLE teams(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN('internal','agency')));
CREATE TABLE brands(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE users(id INTEGER PRIMARY KEY,login_no TEXT NOT NULL UNIQUE,name TEXT NOT NULL,team_id INTEGER NOT NULL REFERENCES teams(id),role TEXT NOT NULL CHECK(role IN('ADMIN','LEAD','ANALYST','EDITOR','OPERATOR','PARTNER')),active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE platforms(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,content_format TEXT NOT NULL CHECK(content_format IN('video','article','image_text')));
CREATE TABLE channel_accounts(id INTEGER PRIMARY KEY,platform_id INTEGER NOT NULL REFERENCES platforms(id),brand_id INTEGER NOT NULL REFERENCES brands(id),team_id INTEGER NOT NULL REFERENCES teams(id),name TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN('active','suspended')),timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai');
CREATE TABLE account_grants(user_id INTEGER NOT NULL REFERENCES users(id),account_id INTEGER NOT NULL REFERENCES channel_accounts(id),access TEXT NOT NULL CHECK(access IN('READ','OPERATE')),valid_from TEXT NOT NULL,valid_to TEXT,PRIMARY KEY(user_id,account_id),CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE TABLE campaigns(id INTEGER PRIMARY KEY,brand_id INTEGER NOT NULL REFERENCES brands(id),name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,objective TEXT NOT NULL CHECK(objective IN('awareness','registration','lead')),CHECK(end_date>=start_date));
CREATE TABLE campaign_accounts(campaign_id INTEGER NOT NULL REFERENCES campaigns(id),account_id INTEGER NOT NULL REFERENCES channel_accounts(id),PRIMARY KEY(campaign_id,account_id));
CREATE TABLE content_items(id INTEGER PRIMARY KEY,campaign_id INTEGER NOT NULL REFERENCES campaigns(id),team_id INTEGER NOT NULL REFERENCES teams(id),topic TEXT NOT NULL,editor_id INTEGER NOT NULL REFERENCES users(id),partner_id INTEGER REFERENCES users(id),brief TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE content_versions(id INTEGER PRIMARY KEY,content_id INTEGER NOT NULL REFERENCES content_items(id),platform_id INTEGER NOT NULL REFERENCES platforms(id),revision INTEGER NOT NULL CHECK(revision>0),title TEXT NOT NULL,body TEXT NOT NULL,asset_uri TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','submitted','approved','rejected')),author_id INTEGER NOT NULL REFERENCES users(id),reviewed_by INTEGER REFERENCES users(id),review_note TEXT,UNIQUE(content_id,platform_id,revision),CHECK((state IN('approved','rejected') AND reviewed_by IS NOT NULL) OR (state IN('draft','submitted') AND reviewed_by IS NULL)));
CREATE TABLE publications(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL REFERENCES content_versions(id),account_id INTEGER NOT NULL REFERENCES channel_accounts(id),status TEXT NOT NULL CHECK(status IN('draft','scheduled','failed','published','removed')),scheduled_at TEXT,published_at TEXT,external_post_id TEXT UNIQUE,failure_reason TEXT,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),UNIQUE(version_id,account_id),CHECK((status IN('published','removed') AND published_at IS NOT NULL AND external_post_id IS NOT NULL) OR (status IN('draft','scheduled','failed') AND published_at IS NULL AND external_post_id IS NULL)),CHECK(status<>'scheduled' OR scheduled_at IS NOT NULL),CHECK(status<>'failed' OR failure_reason IS NOT NULL));
CREATE TABLE publication_events(id INTEGER PRIMARY KEY,publication_id INTEGER NOT NULL REFERENCES publications(id),actor_id INTEGER NOT NULL REFERENCES users(id),from_status TEXT,to_status TEXT NOT NULL CHECK(to_status IN('draft','scheduled','failed','published','removed')),occurred_at TEXT NOT NULL,note TEXT NOT NULL);
CREATE TABLE metric_definitions(platform_id INTEGER NOT NULL REFERENCES platforms(id),code TEXT NOT NULL,label TEXT NOT NULL,unit TEXT NOT NULL,aggregation TEXT NOT NULL CHECK(aggregation IN('daily_additive','cumulative_snapshot')),definition TEXT NOT NULL,PRIMARY KEY(platform_id,code));
CREATE TABLE ingestion_batches(id INTEGER PRIMARY KEY,platform_id INTEGER NOT NULL REFERENCES platforms(id),business_date TEXT NOT NULL,captured_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('complete','partial','failed')),note TEXT NOT NULL,UNIQUE(platform_id,business_date));
CREATE TABLE account_daily_metrics(account_id INTEGER NOT NULL REFERENCES channel_accounts(id),metric_date TEXT NOT NULL,batch_id INTEGER NOT NULL REFERENCES ingestion_batches(id),new_followers INTEGER,unfollows INTEGER,followers_end INTEGER,availability TEXT NOT NULL CHECK(availability IN('complete','missing')),PRIMARY KEY(account_id,metric_date),CHECK(new_followers IS NULL OR new_followers>=0),CHECK(unfollows IS NULL OR unfollows>=0),CHECK(followers_end IS NULL OR followers_end>=0),CHECK(availability<>'missing' OR (new_followers IS NULL AND unfollows IS NULL AND followers_end IS NULL)));
CREATE TABLE publication_daily_metrics(publication_id INTEGER NOT NULL REFERENCES publications(id),metric_date TEXT NOT NULL,batch_id INTEGER NOT NULL REFERENCES ingestion_batches(id),views INTEGER,likes INTEGER,comment_count INTEGER,shares INTEGER,organic_views INTEGER,paid_views INTEGER,availability TEXT NOT NULL CHECK(availability IN('complete','missing')),revision INTEGER NOT NULL CHECK(revision>0),PRIMARY KEY(publication_id,metric_date),CHECK(views IS NULL OR views>=0),CHECK(likes IS NULL OR likes>=0),CHECK(comment_count IS NULL OR comment_count>=0),CHECK(shares IS NULL OR shares>=0),CHECK(organic_views IS NULL OR organic_views>=0),CHECK(paid_views IS NULL OR paid_views>=0),CHECK(organic_views IS NULL OR views=organic_views+paid_views),CHECK(availability<>'missing' OR (views IS NULL AND likes IS NULL AND comment_count IS NULL AND shares IS NULL AND organic_views IS NULL AND paid_views IS NULL)));
CREATE TABLE publication_metric_snapshots(id INTEGER PRIMARY KEY,publication_id INTEGER NOT NULL REFERENCES publications(id),batch_id INTEGER NOT NULL REFERENCES ingestion_batches(id),captured_at TEXT NOT NULL,cumulative_views INTEGER,revision INTEGER NOT NULL,source_note TEXT NOT NULL,UNIQUE(publication_id,captured_at,revision),CHECK(cumulative_views IS NULL OR cumulative_views>=0));
CREATE TABLE ad_sets(id INTEGER PRIMARY KEY,publication_id INTEGER NOT NULL REFERENCES publications(id),campaign_id INTEGER NOT NULL REFERENCES campaigns(id),name TEXT NOT NULL,budget_cents INTEGER NOT NULL CHECK(budget_cents>0),currency TEXT NOT NULL CHECK(currency='CNY'),status TEXT NOT NULL CHECK(status IN('active','paused','closed')));
CREATE TABLE ad_daily_metrics(ad_set_id INTEGER NOT NULL REFERENCES ad_sets(id),metric_date TEXT NOT NULL,spend_cents INTEGER NOT NULL CHECK(spend_cents>=0),impressions INTEGER NOT NULL CHECK(impressions>=0),clicks INTEGER NOT NULL CHECK(clicks BETWEEN 0 AND impressions),platform_reported_conversions INTEGER NOT NULL CHECK(platform_reported_conversions>=0),PRIMARY KEY(ad_set_id,metric_date));
CREATE TABLE tracked_links(id INTEGER PRIMARY KEY,publication_id INTEGER NOT NULL REFERENCES publications(id),campaign_id INTEGER NOT NULL REFERENCES campaigns(id),tracking_code TEXT NOT NULL UNIQUE,landing_path TEXT NOT NULL);
CREATE TABLE landing_daily_metrics(link_id INTEGER NOT NULL REFERENCES tracked_links(id),metric_date TEXT NOT NULL,page_views INTEGER NOT NULL CHECK(page_views>=0),sessions INTEGER NOT NULL CHECK(sessions BETWEEN 0 AND page_views),PRIMARY KEY(link_id,metric_date));
CREATE TABLE conversion_events(id INTEGER PRIMARY KEY,event_key TEXT NOT NULL UNIQUE,campaign_id INTEGER NOT NULL REFERENCES campaigns(id),link_id INTEGER REFERENCES tracked_links(id),event_type TEXT NOT NULL CHECK(event_type IN('registration','lead')),occurred_at TEXT NOT NULL,last_click_at TEXT,attribution TEXT NOT NULL CHECK(attribution IN('last_click_7d','unknown')),quality TEXT NOT NULL CHECK(quality IN('valid','duplicate','invalid')),CHECK((attribution='unknown' AND link_id IS NULL AND last_click_at IS NULL) OR (attribution='last_click_7d' AND link_id IS NOT NULL AND last_click_at IS NOT NULL)));
CREATE TABLE comments(id INTEGER PRIMARY KEY,publication_id INTEGER NOT NULL REFERENCES publications(id),parent_id INTEGER REFERENCES comments(id),author_alias TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('pending','visible','hidden','replied')),reply_text TEXT,handled_by INTEGER REFERENCES users(id),CHECK((state='replied' AND reply_text IS NOT NULL AND handled_by IS NOT NULL) OR state<>'replied'));
CREATE TABLE moderation_events(id INTEGER PRIMARY KEY,comment_id INTEGER NOT NULL REFERENCES comments(id),actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL CHECK(action IN('approve','hide','reply')),occurred_at TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE schema_comments(table_name TEXT NOT NULL,column_name TEXT NOT NULL,comment_zh TEXT NOT NULL,PRIMARY KEY(table_name,column_name));
CREATE INDEX content_editor_idx ON content_items(editor_id,partner_id);
CREATE INDEX publications_account_idx ON publications(account_id,status);
CREATE INDEX publications_version_idx ON publications(version_id);
CREATE INDEX events_publication_idx ON publication_events(publication_id,id);
CREATE INDEX daily_date_idx ON publication_daily_metrics(metric_date,publication_id);
CREATE INDEX snapshots_publication_idx ON publication_metric_snapshots(publication_id,captured_at,revision);
CREATE INDEX ad_publication_idx ON ad_sets(publication_id);
CREATE INDEX comments_publication_idx ON comments(publication_id,state);
CREATE INDEX moderation_comment_idx ON moderation_events(comment_id,id);
CREATE INDEX conversions_campaign_idx ON conversion_events(campaign_id,occurred_at);
CREATE INDEX conversions_link_idx ON conversion_events(link_id,occurred_at);
